import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []
    for _ in range(T):
        try:
            s = next(iterator)
        except StopIteration:
            break

        b_count = s.count('B')
        if b_count % 2 == 1:
            results.append("Chef")
        else:
            results.append("Aleksa")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
